package com.cpf.education.online.common.service;
import com.cpf.common.calendar.api.CpfCalendarService;import com.cpf.common.code.api.CpfCodeService;import com.cpf.common.message.api.CpfMessageSource;import com.cpf.common.parameter.api.CpfParameterService;import com.cpf.foundation.annotation.CpfService;import java.time.LocalDate;import java.util.*;
/** 공통정보 교육 예제의 Service 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfService public class MemberReferenceService {private final CpfCodeService codes;private final CpfMessageSource messages;private final CpfParameterService parameters;private final CpfCalendarService calendars;public MemberReferenceService(CpfCodeService c,CpfMessageSource m,CpfParameterService p,CpfCalendarService cal){codes=c;messages=m;parameters=p;calendars=cal;}public Map<String,Object> resolve(String status,LocalDate date){return Map.of("status",codes.required("MEMBER_STATUS",status),"limit",parameters.requiredValue("member.daily-limit",Long.class),"message",messages.getMessage("member.available",Locale.KOREAN),"businessDay",calendars.isBusinessDay("KR",date));}}
